package com.anderzenn.dorgeshkaanagilitycourse;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DorgeshKaanAgilityCourseTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DorgeshKaanAgilityCourse.class);
		RuneLite.main(args);
	}
}

package com.anderzenn.dorgeshkaanagilitycourse;

import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;

/**
 * Highlights Turgall, the Dorgesh-Kaan engineer, so he's easy to spot to collect
 * the spanner from or hand requested items to.
 */
public class TurgallHighlightOverlay extends Overlay
{
	private final Client client;
	private final DorgeshKaanAgilityCourseConfig config;

	@Inject
	private TurgallHighlightOverlay(Client client, DorgeshKaanAgilityCourseConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightTurgall() || client.getLocalPlayer() == null)
		{
			return null;
		}

		int regionId = WorldPoint.fromLocal(client, client.getLocalPlayer().getLocalLocation()).getRegionID();
		if (regionId != DorgeshKaanConstants.REGION_ID)
		{
			return null;
		}

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc == null || npc.getId() != DorgeshKaanConstants.TURGALL_NPC_ID)
			{
				continue;
			}

			Shape hull = npc.getConvexHull();
			if (hull == null)
			{
				continue;
			}

			Color colour = config.turgallHighlightColour();
			graphics.setColor(colour);
			graphics.setStroke(new BasicStroke(config.courseStrokeWidth()));
			graphics.draw(hull);

			graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), 20));
			graphics.fill(hull);
		}

		return null;
	}
}

package com.anderzenn.dorgeshkaanagilitycourse;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;

/**
 * Warns the player if they're in the course region without the Dorgesh-Kaan spanner.
 */
@Slf4j
public class SpannerWarningOverlay extends OverlayPanel
{
	private final DorgeshKaanAgilityCourse plugin;
	private final BufferedImage spannerIcon;

	@Inject
	private SpannerWarningOverlay(DorgeshKaanAgilityCourse plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panelComponent.setWrap(true);
		panelComponent.setOrientation(ComponentOrientation.HORIZONTAL);
		spannerIcon = loadImage();
	}

	private BufferedImage loadImage()
	{
		try
		{
			return ImageUtil.loadImageResource(DorgeshKaanAgilityCourse.class, "/Spanner.png");
		}
		catch (Exception e)
		{
			log.error("Error loading image: {}", "Spanner.png", e);
			return null;
		}
	}

	public void clearWarning()
	{
		panelComponent.getChildren().clear();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();

		if (spannerIcon != null && plugin.displaySpannerWarning())
		{
			panelComponent.getChildren().add(new ImageComponent(spannerIcon));

			panelComponent.getChildren().add(LineComponent.builder()
					.right("No Spanner!")
					.rightColor(Color.RED)
					.build());

			// Spacing to counter text overlapping with icon
			panelComponent.getChildren().add(LineComponent.builder().left("").build());
			panelComponent.getChildren().add(LineComponent.builder().left("").build());

			panelComponent.getChildren().add(LineComponent.builder()
					.left("Talk to Turgall to receive one.")
					.build());
		}

		return super.render(graphics);
	}
}

package com.anderzenn.dorgeshkaanagilitycourse;

/**
 * The two routes through the Dorgesh-Kaan agility course, and which route is correct
 * is determined entirely by which item the player is currently carrying:
 * <ul>
 *     <li>{@link #DELICATE} - capacitor / fuse / meter -&gt; the grapple (pylon) route,
 *         which requires a crossbow + mith grapple equipped</li>
 *     <li>{@link #HEAVY} - cog / lever / powerbox -&gt; the agility (cable/wall/tunnel/ladder) route</li>
 * </ul>
 * Per the OSRS Wiki: "The heavy items can only be taken back via the Agility route,
 * while the delicate items can only be taken back via the grapple route." The original
 * plugin had this backwards (its variable names and comments called capacitor/fuse/meter
 * the "agility route" items) - the object IDs below have been swapped to match reality,
 * confirmed against the Wiki's obstacle lists: the grapple route is 3 repeated pylons
 * (a single object ID), while the agility route is a chain of distinct obstacles
 * (cable x2 variants, ladder, jutting wall, tunnel - five distinct object IDs).
 * <p>
 * This single enum replaces what used to be three separately-maintained copies of the
 * same item/object-ID lists spread across the overlay and panel classes.
 */
public enum RouteType
{
	DELICATE(
			"Grapple Route",
			new String[]{"capacitor", "fuse", "meter"},
			new int[]{22664}
	),
	HEAVY(
			"Agility Route",
			new String[]{"cog", "lever", "powerbox"},
			new int[]{22569, 22572, 22564, 22552, 22557}
	),
	NONE("No Item", new String[0], new int[0]);

	private final String displayName;
	private final String[] itemNames;
	private final int[] objectIds;

	RouteType(String displayName, String[] itemNames, int[] objectIds)
	{
		this.displayName = displayName;
		this.itemNames = itemNames;
		this.objectIds = objectIds;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/** Item name fragments (lowercase) that identify this route's item in the inventory. */
	public String[] getItemNames()
	{
		return itemNames;
	}

	/** Game/ground object IDs that make up this route's highlighted path. */
	public boolean containsObjectId(int id)
	{
		for (int val : objectIds)
		{
			if (val == id)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Exact (case-insensitive) match against this route's item names - used for
	 * checking dialogue option text and requested-item strings, which are already
	 * single, normalised words (unlike inventory item names, which need substring matching).
	 */
	public boolean containsItemName(String name)
	{
		if (name == null)
		{
			return false;
		}
		for (String candidate : itemNames)
		{
			if (candidate.equalsIgnoreCase(name))
			{
				return true;
			}
		}
		return false;
	}
}

package com.anderzenn.dorgeshkaanagilitycourse;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@PluginDescriptor(
	name = "Dorgesh-Kaan Agility Course",
	description = "provides quality of life information to-do with the Dorgesh-Kaan agility course",
	tags = {"agility","dorgesh-kaan","dorgesh","kaan","dorgeshkaan","helper","agilityhelper","course","agilitycourse","agility course"}
)
public class DorgeshKaanAgilityCourse extends Plugin
{
	private static final String CONFIG_GROUP = "DorgeshKaanAgilityCourseConfig";
	private static final Pattern REQUEST_PATTERN = Pattern.compile("The engineer asks you to get a (\\w+) or a (\\w+)");
	private static final Pattern LAP_COUNT_PATTERN = Pattern.compile("Your Dorgesh-Kaan Agility lap count is: (\\d+)");

	private static final String GRAPPLE_ITEM_NAME_FRAGMENT = "mith grapple";
	private static final String CROSSBOW_NAME_FRAGMENT = "crossbow";
	private static final String EXCLUDED_CROSSBOW_NAME = "love crossbow";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DorgeshKaanAgilityCourseConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private DorgeshKaanOverlay overlay;

	@Inject
	private SpannerWarningOverlay spannerWarningOverlay;

	@Inject
	private TurgallHighlightOverlay turgallHighlightOverlay;

	@Inject
	private CourseHighlightOverlay courseHighlightOverlay;

	public String requestedItem1 = null;
	public String requestedItem2 = null;
	private boolean wasInRegion = false;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		overlayManager.add(spannerWarningOverlay);
		overlayManager.add(turgallHighlightOverlay);
		overlayManager.add(courseHighlightOverlay);

		// Load saved items from config. The config default is "" rather than null,
		// so normalise that here - otherwise the panel tries to render a row for an
		// empty item name and throws on capitalising it.
		requestedItem1 = emptyToNull(config.requestedItem1());
		requestedItem2 = emptyToNull(config.requestedItem2());

		// Fixes https://github.com/Anderzenn/dorgesh-kaan-agility-course/issues/1
		clientThread.invokeLater(this::updateOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlayManager.remove(spannerWarningOverlay);
		overlayManager.remove(turgallHighlightOverlay);
		overlayManager.remove(courseHighlightOverlay);
		overlay.clearOverlay();
		spannerWarningOverlay.clearWarning();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());

		Matcher requestMatcher = REQUEST_PATTERN.matcher(message);
		if (requestMatcher.find())
		{
			setRequestedItems(requestMatcher.group(1), requestMatcher.group(2));
			updateOverlay();
			return;
		}

		Matcher lapCountMatcher = LAP_COUNT_PATTERN.matcher(message);
		if (lapCountMatcher.find())
		{
			clearRequestedItems();
			overlay.clearOverlay();
			updateOverlay();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		boolean inRegion = isInRegion();
		if (inRegion != wasInRegion)
		{
			wasInRegion = inRegion;
			updateOverlay();
		}

		if (inRegion)
		{
			updateOverlay();
		}
	}

	private void setRequestedItems(String item1, String item2)
	{
		requestedItem1 = item1;
		requestedItem2 = item2.equalsIgnoreCase("power") ? "powerbox" : item2;

		configManager.setConfiguration(CONFIG_GROUP, "requestedItem1", requestedItem1);
		configManager.setConfiguration(CONFIG_GROUP, "requestedItem2", requestedItem2);
	}

	private void clearRequestedItems()
	{
		requestedItem1 = null;
		requestedItem2 = null;

		configManager.unsetConfiguration(CONFIG_GROUP, "requestedItem1");
		configManager.unsetConfiguration(CONFIG_GROUP, "requestedItem2");
	}

	private void updateOverlay()
	{
		if (!isInRegion())
		{
			overlay.clearOverlay();
			spannerWarningOverlay.clearWarning();
			return;
		}

		if (config.highlightOption())
		{
			highlightDialogueOption();
		}

		overlay.updateOverlay(requestedItem1, requestedItem2);
	}

	private boolean isInRegion()
	{
		return client.getLocalPlayer() != null
				&& WorldPoint.fromLocal(client, client.getLocalPlayer().getLocalLocation()).getRegionID() == DorgeshKaanConstants.REGION_ID;
	}

	/**
	 * Determines which route is currently correct, based on the item(s) in the player's
	 * inventory. The delicate/grapple route additionally requires a crossbow + mith
	 * grapple equipped - without one, it's not reported as a usable route (see
	 * {@link #isItemSelectable(String)}). Delicate takes priority in the unusual case
	 * both item types are held at once (e.g. a leftover item from a previous lap).
	 */
	public RouteType getCurrentRouteType()
	{
		if (hasAnyItem(RouteType.DELICATE.getItemNames()) && hasGrapple())
		{
			return RouteType.DELICATE;
		}
		if (hasAnyItem(RouteType.HEAVY.getItemNames()))
		{
			return RouteType.HEAVY;
		}
		return RouteType.NONE;
	}

	public boolean checkInventoryForItem(String targetName)
	{
		return hasAnyItem(new String[]{targetName});
	}

	/**
	 * @return true if this item name belongs to the delicate/grapple route (capacitor, fuse, meter).
	 */
	public boolean isDelicateItem(String itemName)
	{
		return RouteType.DELICATE.containsItemName(itemName);
	}

	/**
	 * An item is "selectable" unless it's a delicate item and the player doesn't have a
	 * grapple equipped - since the grapple route can't actually be completed without one.
	 */
	public boolean isItemSelectable(String itemName)
	{
		return !isDelicateItem(itemName) || hasGrapple();
	}

	/**
	 * @return true if the player has a crossbow (any, excluding the love crossbow) equipped
	 * in the weapon slot, and a mith grapple equipped in the ammunition slot.
	 */
	public boolean hasGrapple()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return false;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		Item ammo = equipment.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());

		if (weapon == null || ammo == null || weapon.getId() <= 0 || ammo.getId() <= 0)
		{
			return false;
		}

		String weaponName = itemManager.getItemComposition(weapon.getId()).getName().toLowerCase();
		String ammoName = itemManager.getItemComposition(ammo.getId()).getName().toLowerCase();

		boolean hasCrossbow = weaponName.contains(CROSSBOW_NAME_FRAGMENT) && !weaponName.contains(EXCLUDED_CROSSBOW_NAME);
		boolean hasMithGrapple = ammoName.contains(GRAPPLE_ITEM_NAME_FRAGMENT);

		return hasCrossbow && hasMithGrapple;
	}

	private boolean hasAnyItem(String[] itemNames)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return false;
		}

		for (Item item : inventory.getItems())
		{
			String name = itemManager.getItemComposition(item.getId()).getName().toLowerCase();
			for (String target : itemNames)
			{
				if (name.contains(target.toLowerCase()))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * @return true if the player does NOT currently have the Dorgesh-Kaan spanner.
	 * (Previously named {@code hasSpanner()} despite returning the opposite - renamed
	 * for clarity, behaviour unchanged.)
	 */
	public boolean isMissingSpanner()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return true;
		}

		for (Item item : inventory.getItems())
		{
			if (item.getId() == ItemID.DORGESH_SPANNER)
			{
				return false;
			}
		}
		return true;
	}

	public boolean displaySpannerWarning()
	{
		return isInRegion() && isMissingSpanner();
	}

	private void highlightDialogueOption()
	{
		clientThread.invokeLater(() -> {
			Widget dialogueOptions = client.getWidget(InterfaceID.CHATMENU, 1);
			if (dialogueOptions == null || dialogueOptions.getChildren() == null)
			{
				return;
			}

			for (Widget option : dialogueOptions.getChildren())
			{
				if (option == null || option.getText() == null)
				{
					continue;
				}

				String optionText = option.getText().trim();
				if (isRequestedItem(optionText))
				{
					option.setTextColor(config.highlightColour().getRGB());
				}
			}
		});
	}

	private boolean isRequestedItem(String optionText)
	{
		if (!isItemSelectable(optionText))
		{
			return false;
		}
		return optionText.equalsIgnoreCase(requestedItem1) || optionText.equalsIgnoreCase(requestedItem2);
	}

	private static String emptyToNull(String s)
	{
		return (s == null || s.isEmpty()) ? null : s;
	}

	@Provides
	DorgeshKaanAgilityCourseConfig dorgeshKaanAgilityCourseConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DorgeshKaanAgilityCourseConfig.class);
	}
}

package com.anderzenn.dorgeshkaanagilitycourse;

import java.awt.Color;

/**
 * Picks the configured colour for a given route. This used to be a default method on
 * {@link DorgeshKaanAgilityCourseConfig}, but RuneLite's config proxy intercepts every
 * interface method call - including default ones - and since a plain default method has
 * no {@code @ConfigItem}, the proxy logged a warning and returned null instead of running
 * the method body, which caused a NullPointerException wherever the colour was used.
 * Keeping this as an ordinary static helper avoids the proxy entirely.
 */
final class RouteColours
{
	private RouteColours()
	{
		// no instances
	}

	static Color forRoute(DorgeshKaanAgilityCourseConfig config, RouteType route)
	{
		return route == RouteType.HEAVY ? config.heavyRouteColour() : config.highlightCourseColour();
	}
}

package com.anderzenn.dorgeshkaanagilitycourse;

/**
 * Shared, plugin-wide constants for the Dorgesh-Kaan agility course.
 * Centralised here so the overlays and the main plugin class don't each
 * keep their own copies of the same magic numbers.
 */
final class DorgeshKaanConstants
{
	private DorgeshKaanConstants()
	{
		// no instances
	}

	/**
	 * Region ID shared by all three floors of the course. Note that inside the
	 * instanced template, the raw region ID reported by {@code WorldPoint.fromLocalInstance}
	 * stays 10833 regardless of floor - the actual floor has to be read from the
	 * player's resolved {@code getWorldLocation()} plane instead (0 = lower, 2 = middle, 3 = upper).
	 */
	static final int REGION_ID = 10833;

	/** Plane the boiler-room floor (where the course objects/ground items live) resolves to. */
	static final int COURSE_PLANE = 3;

	/** NPC ID for Turgall, the engineer who hands out the spanner and item requests. */
	static final int TURGALL_NPC_ID = 2295;

	/** Ladder object ID on the ground floor - kept for future use (e.g. fall recovery guidance). */
	static final int GROUND_FLOOR_LADDER_ID = 22600;
}

package com.anderzenn.dorgeshkaanagilitycourse;

import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;

/**
 * Highlights the ground route(s) of the Dorgesh-Kaan agility course:
 * <ul>
 *     <li>Before the player has picked up an item, both possible outbound routes to the
 *         generator are highlighted (the grapple route only if a grapple is equipped,
 *         since it's unusable without one either direction).</li>
 *     <li>Once the player is carrying an item, only the single correct return route is
 *         highlighted, since the other route can't be used to bring that item back.</li>
 * </ul>
 */
public class CourseHighlightOverlay extends Overlay
{
	private final Client client;
	private final DorgeshKaanAgilityCourseConfig config;
	private final DorgeshKaanAgilityCourse plugin;

	@Inject
	private CourseHighlightOverlay(Client client, DorgeshKaanAgilityCourseConfig config, DorgeshKaanAgilityCourse plugin)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightCourse() || client.getLocalPlayer() == null)
		{
			return null;
		}

		// Region ID needs the instance-resolved point (stays 10833 on every floor);
		// the plane needs the player's resolved world location (0/2/3 per floor).
		WorldPoint instancePoint = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
		WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();

		if (instancePoint.getRegionID() != DorgeshKaanConstants.REGION_ID || playerLocation.getPlane() != DorgeshKaanConstants.COURSE_PLANE)
		{
			return null;
		}

		WorldView worldView = client.getTopLevelWorldView();
		Tile[][][] tiles = worldView.getScene().getTiles();
		int plane = worldView.getPlane();

		RouteType route = plugin.getCurrentRouteType();
		if (route != RouteType.NONE)
		{
			// Carrying an item - only the matching return route is usable.
			highlightRoute(graphics, tiles, plane, route);
		}
		else
		{
			// No item yet - show the outbound route(s) toward the generator.
			// The agility route needs no equipment; the grapple route is only shown if usable.
			highlightRoute(graphics, tiles, plane, RouteType.HEAVY);
			if (plugin.hasGrapple())
			{
				highlightRoute(graphics, tiles, plane, RouteType.DELICATE);
			}
		}

		return null;
	}

	private void highlightRoute(Graphics2D graphics, Tile[][][] tiles, int plane, RouteType route)
	{
		Color colour = RouteColours.forRoute(config, route);

		for (Tile[] column : tiles[plane])
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}

				for (GameObject go : tile.getGameObjects())
				{
					if (go != null && route.containsObjectId(go.getId()))
					{
						drawOutline(graphics, go.getConvexHull(), colour);
					}
				}

				GroundObject groundObj = tile.getGroundObject();
				if (groundObj != null && route.containsObjectId(groundObj.getId()))
				{
					drawOutline(graphics, groundObj.getConvexHull(), colour);
				}
			}
		}
	}

	private void drawOutline(Graphics2D graphics, Shape shape, Color colour)
	{
		if (shape == null)
		{
			return;
		}

		graphics.setColor(colour);
		graphics.setStroke(new BasicStroke(config.courseStrokeWidth()));
		graphics.draw(shape);

		graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), 20));
		graphics.fill(shape);
	}
}

package com.anderzenn.dorgeshkaanagilitycourse;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.*;

@ConfigGroup("DorgeshKaanAgilityCourseConfig")
public interface DorgeshKaanAgilityCourseConfig extends Config
{
	/* Config Sections */
	@ConfigSection(
			name = "Course QoL Features",
			description = "Settings for enabling or disabling QoL features in the plugin",
			position = 0
	)
	String courseFeatures = "course qol features";

